/*
 * A136158  Triangle whose rows are generated by A136157^n * [1, 1, 0, 0, 0,
 *          ...].
 * https://oeis.org/A136158
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, tabl
 * Formula:   not stated
 * Range:     u8 n <= 21, u16 n <= 55, u32 n <= 173, u64 n <= 601,
 *            u128 n <= 1325, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Triangle A136158:  a(n) is the (row‑major) entry T(r,k) of the
 * triangle defined by
 *
 *    T(0,0) = 1
 *    T(n,k) = 3*T(n-1,k) + T(n-1,k-1)   for n > 0, 0 ≤ k ≤ n
 *
 * with the convention T(n,k)=0 for k<0 or k>n.
 *
 * For a given index n one finds the row r with
 *      r*(r+1)/2 ≤ n < (r+1)*(r+2)/2
 * and the column k = n – r*(r+1)/2.
 * Then
 *
 *      T(r,k) = binom(r-1,k) * 3^(r-1-k)
 *          + (k>0 ? binom(r-1,k-1) * 3^(r-k) : 0) .
 *
 * The function below implements this formula using only integer
 * arithmetic.  Auxiliary routines _binom and _pow3 are supplied
 * locally to avoid dependencies on external headers.  The code
 * is valid C11 and C++17, uses only the allowed operators, and
 * works for 64‑bit integers as well as arbitrary‑precision builds.
 */

#include <stdint.h>

static seq_t _pow3(idx_t e)
{
    seq_t result = 1;
    seq_t base   = 3;
    while (e)
    {
        if (e & 1U)
            result = result * base;
        base = base * base;
        e >>= 1U;
    }
    return result;
}

static seq_t _binom(idx_t n, idx_t k)
{
    if (k > n)
        return 0;
    if (k > n - k)
        k = n - k;
    seq_t res = 1;
    for (idx_t i = 1; i <= k; ++i)
    {
        res = res * (seq_t)(n - k + i);
        res = res / (seq_t)i;
    }
    return res;
}

seq_t a(idx_t n)
{
    /* Find the row r such that r*(r+1)/2 ≤ n < (r+1)*(r+2)/2 */
    idx_t low = 0, high = n;
    while (low < high)
    {
        idx_t mid = low + (high - low + 1) / 2;
        __uint128_t prod = ((__uint128_t)mid * (mid + 1U)) / 2U;
        if (prod <= n)
            low = mid;
        else
            high = mid - 1U;
    }
    idx_t r = low;

    /* Index of the first element of row r */
    idx_t offset = (idx_t)(((__uint128_t)r * (r + 1U)) / 2U);
    idx_t k = n - offset;

    /* Handle the trivial first row */
    if (r == 0U)
        return 1;

    /* Compute the closed‑form value of T(r,k) */
    seq_t part1 = 0, part2 = 0;

    if (k <= r - 1U)
    {
        part1 = _binom(r - 1U, k);
        part1 = part1 * _pow3(r - 1U - k);
    }
    if (k >= 1U)
    {
        part2 = _binom(r - 1U, k - 1U);
        part2 = part2 * _pow3(r - k);
    }

    return part1 + part2;
}
